/// <summary>
/// Method to display printer name.
/// </summary>
/// <returns>
/// Name of the printer that work user belongs to.
/// </returns>
[
    SysClientCacheDataMethodAttribute(true)
]
public boolean validateDelete()
{
    boolean ret;

    ret = super();

    if (WHSWorkUser::find(this.UserId).AVAUserDefaultPrinterCode == this.PrinterCode)
    {
        ret = checkFailed("@NDX:AVANotDefaultPrinter");
    }

    return ret;
}

/// <summary>
/// Checks if a specific <c>ALNWHSWorkUserPrinter</c> record exists.
/// </summary>
/// <param name="_userId">
/// User id of the record.
/// </param>
/// <param name="_printerCode">
/// Printer id of the record.
/// </param>
/// <returns>
/// True if the record exists.
/// </returns>
public static boolean exist(WHSUserId       _userId,
                            AVAPrinterCode  _printerCode)
{
    boolean                 ret;
    AVAWHSWorkUserPrinter   workUserPrinter;

    if (_userId && _printerCode)
    {
        select firstonly RecId from workUserPrinter
            where workUserPrinter.UserId        == _userId
               && workUserPrinter.PrinterCode   == _printerCode;

        if (workUserPrinter.RecId)
        {
            ret = true;
        }
    }

    return ret;
}

/// <summary>
/// Get Printer codes that the work user has access to.
/// </summary>
/// <param name="_userId">
/// Work user ID used to get the printer codes it has access to.
/// </param>
/// <returns>
/// Pipe-delimited printer codes that the work user has access to.
/// </returns>
public static str getPrinterCodesByUser(WHSUserId _userId)
{
    #WHSRF

    str elements;

    if (_userId)
    {
        AVAWHSWorkUserPrinter userPrinter;

        while select PrinterCode from userPrinter
            where userPrinter.UserId == _userId
        {
            if (elements)
            {
                elements += #ListSeparator + strFmt('%1', userPrinter.PrinterCode);
            }
            else
            {
                elements = strFmt('%1', userPrinter.PrinterCode);
            }
        }
    }

    return elements;
}
